layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.80){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vP = position.xy;
      if (aK < .5){ float S = .95; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }
      else if (aK < 1.5){ vec3 f = cameraPosition - aO; f.y = 0.; f = normalize(f); vec3 rt = vec3(f.z, 0., -f.x);
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + rt*position.x*.42 + vec3(0., .75 + (position.y*.5 + .5)*1.15, 0.), 1.); }   /* short and thin: waist → just above the shoulders, never a column over the body */
      else { vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.2, 0.), 1.); mv.xyz += normalize(-mv.xyz)*.3; float S = .75; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv; }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    float h1(float n){ return fract(sin(n*91.7)*43758.5); }
    vec2 SP(float i){ return 1.25*(i < .5 ? vec2(-.32, .02) : i < 1.5 ? vec2(-.17, .22) : i < 2.5 ? vec2(.04, .3) : i < 3.5 ? vec2(.24, .19) : vec2(.34, -.04)); }   /* a small constellation (5 stars, crown-like arc) */
    float sdSeg(vec2 p, vec2 a, vec2 b){ vec2 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba)/max(dot(ba, ba), 1e-6), 0., 1.); return length(pa - ba*h); }
    float spark(vec2 q, float s){ float r = length(q), a = atan(q.y, q.x); return pow(abs(cos(a*2.)), 14.)*exp(-r/s*1.3) + exp(-r*r/(s*s*.06)); }
    void main(){
      float lum = 0., hot = 0., t = vU/0.80;
      if (vK < .5){
        float r = length(vP), e = 1. - pow(1. - clamp(vU/.35, 0., 1.), 3.), R = .2 + .6*e, f = (vU < .033 ? 1.5 : 1.)*(1. - smoothstep(.55, 1., t));
        lum += exp(-pow(abs(r - R)/.016, 2.4))*f; hot += lcore(r - R, .005)*f*.6;
        lum *= smoothstep(.95, .85, r); hot *= smoothstep(.95, .85, r);
      } else if (vK < 1.5){
        // Heal: thin streaks rise from the feet in a soft ease-out and open outward a little as they go
        float x = vP.x, y = vP.y*.5 + .5, k = 1. - pow(1. - clamp(vU/.55, 0., 1.), 3.), f = 1. - smoothstep(.5, 1., t);
        for (int i=0;i<4;i++){
          float fi = float(i), ox = (h1(fi) - .5)*1.1*(.4 + .6*y), dl = h1(fi + 3.)*.12;
          float kk = 1. - pow(1. - clamp((vU - dl)/.55, 0., 1.), 3.), head = kk*1.05, tail = head - .35;
          lum += exp(-pow((x - ox)/.03, 2.))*smoothstep(tail, tail + .2, y)*smoothstep(head + .02, head - .1, y)*(.6 + .4*h1(fi + 9.));
          vec2 sp = vec2(x - ox*.8, y - head*.9);                           // a small sparkle riding each streak
          float sa = atan(sp.y, sp.x), sr = length(sp*vec2(1., 2.3));
          lum += pow(abs(cos(sa*2.)), 12.)*exp(-sr*40.)*.8;
        }
        lum *= f*smoothstep(1., .75, abs(x))*smoothstep(1., .85, y); hot = lum*.3;
      } else if (vK > 2.5){
        /* Ether II (buff): a small constellation draws itself on the chest - stars light up one by one, joined by faint
           threads of light - then it drifts up and fades. Only when the ally already had a Buff. */
        float t = vU/.6, g = clamp(vU/.3, 0., 1.)*4., f = 1. - smoothstep(.55, 1., t);
        vec2 p = vP - vec2(0., .12*t);
        for (int i=0;i<5;i++){ float fi = float(i);
          if (fi < 4.){ float l = clamp(g - fi, 0., 1.); if (l > 0.){ vec2 A = SP(fi), B = mix(A, SP(fi + 1.), l);
            float d = sdSeg(p, A, B); lum += exp(-d*d/.00008)*.45*f; } }
          float on = clamp((g - fi + 1.)*3., 0., 1.), fl = exp(-max(g - fi + 1., 0.)*1.2);            /* each star flashes as the thread reaches it */
          float s = spark(p - SP(fi), .045 + .025*fl)*on*(.7 + .8*fl);
          lum += s*f; hot += exp(-dot(p - SP(fi), p - SP(fi))*4000.)*on*f; }
        lum *= smoothstep(.75, .68, length(vP)); hot *= smoothstep(.75, .68, length(vP));
      } else {
        // damage: ring and rays pulled inward (ease-in), then a 2-frame pop at the centre
        float r = length(vP), a = atan(vP.y, vP.x), k = clamp(vU/.22, 0., 1.), R = .7*(1. - k*k*k);
        float f = step(vU, .22), pop = vU >= .22 && vU < .253 ? 1. : 0., after = vU > .22 ? exp(-(vU - .22)*14.) : 0.;
        lum += exp(-pow(abs(r - R)/.02, 2.4))*f;
        float N = 8., fa = floor(a/6.2832*N + .5), ac = fa/N*6.2832, d = abs(sin(a - ac))*r;
        lum += exp(-pow(d/.012, 2.))*smoothstep(R + .2, R, r)*smoothstep(R - .25, R - .05, r)*f*.8;
        lum += exp(-r*r*50.)*(pop*2. + after*.8); hot = exp(-r*r*200.)*(pop*2. + after) + lcore(r - R, .006)*f*.5;
        lum *= smoothstep(.75, .65, r); hot *= smoothstep(.75, .65, r);
      }
      vec3 o = uOrange*lum + mix(uGold, vec3(1.), .5)*hot;
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.);
    }
